INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 17, 'theory', 'Квиз: RAID и SMART');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 0, 'Четыре диска по 4 ТБ собраны в raid5. Какова полезная ёмкость и сколько отказов массив переживает гарантированно?', '["16 ТБ и два отказа", "8 ТБ и один отказ", "12 ТБ и один отказ", "12 ТБ и два отказа"]', 2, 'В raid5 одна чётность: ёмкость (N−1) дисков, то есть 12 ТБ, и гарантированно один отказ. Два отказа переживает только raid6.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 1, 'Что означает запись «[4/3] [UUU_]» в /proc/mdstat?', '["Работают три массива из четырёх", "Массив синхронизирован на 75 процентов", "Четвёртый диск — горячий запасной", "Положено четыре диска, работают три, четвёртый выпал"]', 3, 'Первая цифра — сколько дисков должно быть, вторая — сколько работает; подчёркивание в строке из букв U стоит на месте выпавшего диска. Проценты синхронизации показывает отдельная строка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 2, 'В каком порядке заменяют отказавший диск sdc1 в массиве md0?', '["--fail, --remove, замена диска, --add", "--add, --remove, --fail, замена диска", "Замена диска, --remove, --add, --fail", "--remove, замена диска, --fail, --add"]', 0, 'Работающий участник нельзя убрать: сначала его помечают отказавшим, потом удаляют, меняют железо и только затем добавляют новый диск, после чего начинается восстановление.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 3, 'smartctl -H пишет PASSED, но сырые значения атрибутов 197 и 198 равны 8. Что разумно сделать?', '["Ничего: PASSED означает, что диск здоров", "Следить за ростом и готовить замену: PASSED лишь говорит, что порог не пересечён", "Перезагрузить сервер, чтобы счётчики сбросились", "Отключить SMART в настройках диска"]', 1, 'Вердикт PASSED не означает, что диск здоров: пороги у предотказных атрибутов часто далеки, а ненулевые ожидающие и неисправимые секторы — реальный признак износа. Перезагрузка счётчики не обнуляет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 4, 'Какое поле блока здоровья NVMe показывает долю израсходованного ресурса накопителя?', '["Available Spare", "Critical Warning", "Percentage Used", "Unsafe Shutdowns"]', 2, 'Percentage Used — оценка производителя, сколько ресурса израсходовано; 100 значит, что расчётный ресурс выработан. Available Spare показывает остаток резервных блоков, а Critical Warning — набор битов тревог.');
